func:
// Keep a persistent context or combine incoming signals
// For example, if you trigger this function whenever any output changes:
// DEBUG: See what is actually arriving from the PLC
//node.warn("Incoming Topic: " + msg.topic + " | Payload: " + JSON.stringify(msg.payload));

context.set("machineState", context.get("machineState") || {
    relay1: false,
    relay2: false,
    relay3: false,
    relay4: false,
    motorpwm1: 0,
    motorpwm2: 0,
    btn1: false,
    btn2: false,
    btn3: false,
    svbtn1: false
});

let state = context.get("machineState");

// Update the specific output based on the topic or incoming msg

if (msg.topic === "polling_qx") {
    state.relay1 = msg.payload[0];
    state.relay2 = msg.payload[1];
    state.relay3 = msg.payload[2];
    state.relay4 = msg.payload[3];
}
else if (msg.topic === "polling_qw") {
    state.motorpwm1 = msg.payload[0];
    state.motorpwm2 = msg.payload[1];
}
else if (msg.topic === "polling_inputs"){
    state.btn1 = msg.payload[0];
    state.btn2 = msg.payload[1];
    state.btn3 = msg.payload[2];
}
msg.payload = state;
return msg;

// Retrieve or initialize the persistent state for register 32
let regValue = context.get('reg32') || 0;

// Check which button command came in and update the bit mask
if (msg.payload && msg.topic == 'supervision') {
    node.warn(" | Payload: " + JSON.stringify(msg.payload));
    if (msg.payload.svbtn1 !== undefined) {
        if (msg.payload.svbtn1) {
            regValue |= (1 << 0); // Set Bit 0 (Decimal 1)
        } else {
            regValue &= ~(1 << 0); // Clear Bit 0
        }
    }
    if (msg.payload.svbtn2 !== undefined) {
        if (msg.payload.svbtn2) {
            regValue |= (1 << 1); // Set Bit 1 (Decimal 2)
        } else {
            regValue &= ~(1 << 1); // Clear Bit 1
        }
    }
    if (msg.payload.svbtn3 !== undefined) {
        if (msg.payload.svbtn3) {
            regValue |= (1 << 2); // Set Bit 2 (Decimal 4)
        } else {
            regValue &= ~(1 << 2); // Clear Bit 2
        }
    }
}

// Save state back to context
context.set('reg32', regValue);

// Modbus FC6 strictly requires a raw number for msg.payload
msg.payload = regValue;

return msg;

// Extract the value (Modbus read nodes usually return an array in msg.payload)
//let val = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;

// Update the visual status text and indicator directly under this node
node.status({
    fill: "green",    // Color options: "red", "green", "yellow", "blue", "grey"
    shape: "dot",     // Shape options: "dot" or "ring"
    //text: "Value: " + val
    text: "Value: " + msg.payload
});

// Pass the message along to the rest of the flow
return msg;
